#!/usr/bin/env node
// Pilot Readiness E2E V1 · deterministic, self-contained run (CI and local reproduction).
// Creates a FRESH synthetic root under the OS temp directory, then:
//   init (controlled CLI bootstrap) → schema check → start → full browser journey → stop/start →
//   persistence check → quiesced backup → restore into a separate new root → restored-copy check →
//   original re-checked unchanged.
// No fixed credentials (generated by init, kept in the temp root), no dependency on N-029, on any
// local runtime or on real Cloud. Requires a built frontend (pnpm build) and a Chrome/Chromium
// (WORKOS_E2E_CHROME, or the default path used by e2e/pilot/pilot-journey.mjs).
// Usage: node scripts/pilot-e2e-ci.mjs [--evidence DIR] [--port 8895]
import { spawnSync } from "node:child_process";
import { existsSync, mkdirSync, mkdtempSync, readFileSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const flag = (n) => { const i = process.argv.indexOf(`--${n}`); return i >= 0 ? process.argv[i + 1] : null; };
const PORT = Number(flag("port") ?? 8895);
const RESTORED_PORT = PORT + 2;
const work = mkdtempSync(join(process.env.RUNNER_TEMP || tmpdir(), "workos-pilot-e2e-"));
const ROOT = join(work, "N-029_CI");
const RESTORED = join(work, "N-029_CI_RESTORED");
const BACKUPS = join(work, "N-029_CI-backups");
const EVIDENCE = resolve(flag("evidence") ?? join(repoRoot, "evidence", "WORKOS_PILOT_READINESS_E2E_V1", "ci"));
mkdirSync(EVIDENCE, { recursive: true });
const env = { ...process.env, WORKOS_PILOT_E2E_ALLOW_TEMP: "1" };
const summary = { startedAt: new Date().toISOString(), work, phases: [] };

function run(label, args, { capture = false } = {}) {
  console.log(`\n### ${label}`);
  const r = spawnSync(process.execPath, args, { cwd: repoRoot, env, encoding: "utf8", stdio: capture ? ["ignore", "pipe", "inherit"] : "inherit" });
  if (capture && r.stdout) process.stdout.write(r.stdout);
  summary.phases.push({ label, exitCode: r.status });
  if (r.status !== 0) { finish(false, label); }
  return r.stdout ?? "";
}
const launcher = (cmd, root, port, extra = []) => ["scripts/pilot-e2e.mjs", cmd, "--root", root, "--port", String(port), "--backup-root", BACKUPS, ...extra];
const journey = (root, port, evidence, steps) => ["e2e/pilot/pilot-journey.mjs", "--base", `http://127.0.0.1:${port}`, "--root", root, "--evidence", evidence, ...(steps ? ["--steps", steps] : [])];
let started = [];
function finish(ok, failedAt = null) {
  for (const [root, port] of started) spawnSync(process.execPath, launcher("stop", root, port), { cwd: repoRoot, env, stdio: "inherit" });
  started = [];
  summary.finishedAt = new Date().toISOString();
  summary.result = ok ? "PASS" : "FAIL";
  summary.failedAt = failedAt;
  writeFileSync(join(EVIDENCE, "ci-run-summary.json"), `${JSON.stringify(summary, null, 2)}\n`);
  console.log(`\nPILOT_E2E_CI = ${summary.result}${failedAt ? ` (failed at: ${failedAt})` : ""}`);
  process.exit(ok ? 0 : 1);
}

if (!existsSync(join(repoRoot, "dist", "index.html"))) { console.error("dist/ missing: run pnpm build first"); process.exit(2); }

run("init (controlled CLI bootstrap, fresh root)", launcher("init", ROOT, PORT));
const schema = JSON.parse(run("schema ledgers", launcher("schema", ROOT, PORT), { capture: true }));
summary.schema = { controlLast: schema.control.last, planes: schema.planes.map((p) => p.last) };
if (!schema.control.matchesRepository || !schema.planes.every((p) => p.matchesRepository)) finish(false, "schema mismatch");
run("start", launcher("start", ROOT, PORT)); started.push([ROOT, PORT]);
run("browser journey (full chain)", journey(ROOT, PORT, join(EVIDENCE, "journey")));
run("stop", launcher("stop", ROOT, PORT)); started = [];
run("restart", launcher("start", ROOT, PORT)); started.push([ROOT, PORT]);
run("persistence after restart", journey(ROOT, PORT, join(EVIDENCE, "persistence"), "persistence"));
run("stop for quiesced backup", launcher("stop", ROOT, PORT)); started = [];
const backupOut = run("backup", launcher("backup", ROOT, PORT), { capture: true });
const backupPath = backupOut.match(/BACKUP = (.+)/)?.[1]?.trim();
if (!backupPath || backupPath === "null") finish(false, "backup path not reported");
run("restore into a separate new root", launcher("restore", ROOT, PORT, ["--backup", backupPath, "--target", RESTORED]));
run("start restored copy", launcher("start", RESTORED, RESTORED_PORT)); started.push([RESTORED, RESTORED_PORT]);
run("restored copy: data, audit, representative flow", journey(RESTORED, RESTORED_PORT, join(EVIDENCE, "restored"), "restored"));
run("stop restored copy", launcher("stop", RESTORED, RESTORED_PORT)); started = [];
run("restart original", launcher("start", ROOT, PORT)); started.push([ROOT, PORT]);
run("original unchanged by backup/restore", journey(ROOT, PORT, join(EVIDENCE, "original-after-restore"), "persistence"));
summary.ledger = JSON.parse(readFileSync(join(ROOT, "pilot-e2e-ledger.json"), "utf8")).entries.map((e) => e.step);
finish(true);
